solutionCode:
pub fn tema(escuro: bool, versao: i32) -> String {
    let rotulo = if escuro {
        String::from("tema escuro")
    } else {
        String::from("tema claro")
    };
    format!("{} v{}", rotulo, versao + 1)
}

testsCode:
use desafio::tema;

#[test]
fn testa_o_tema_escuro() {
    assert_eq!(tema(true, 2), "tema escuro v3");
}

#[test]
fn testa_o_tema_claro() {
    assert_eq!(tema(false, 0), "tema claro v1");
}
